BEGIN NOT ATOMIC
DECLARE HELD SMALLINT DEFAULT 0;
DECLARE FAILED SMALLINT DEFAULT 0;
DECLARE RELEASE_FAILED SMALLINT DEFAULT 0;
DECLARE ACQUIRED TIMESTAMP(6);
DECLARE RELEASED TIMESTAMP(6);
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION SET FAILED=1;
DECLARE EXIT HANDLER FOR SQLWARNING SET FAILED=1;
DECLARE EXIT HANDLER FOR NOT FOUND SET FAILED=1;
CALL QSYS2.QCMDEXC('ALCOBJ OBJ((DCNC0966/A *FILE *EXCLRD A) (DCNC0966/B *FILE *EXCLRD B) (DCNC0966/M *FILE *EXCLRD M) (DCNC0966/U *FILE *EXCLRD U)) WAIT(1) CONFLICT(*RQSRLS) SCOPE(*JOB)');
SET HELD=1;
SET ACQUIRED=CURRENT_TIMESTAMP;
CALL QSYS2.QCMDEXC('SNDJRNE JRN(DCNC0966/QSQJRN) TYPE(DN) ENTDTA(''DCGB1 E0C058D978EC40ECAFAC26A5CD835BBD N 1EB812B042F605BBF5B5A5357810DE9B8F413280E3CC8E1514A8066B0B1691A3'') FILE(*NONE) FORCE(*NO) OVRSTATE(*NONE) OVRRMTFTR(*NONE)');
END;
IF HELD=1 THEN
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION SET RELEASE_FAILED=1;
DECLARE EXIT HANDLER FOR SQLWARNING SET RELEASE_FAILED=1;
DECLARE EXIT HANDLER FOR NOT FOUND SET RELEASE_FAILED=1;
CALL QSYS2.QCMDEXC('DLCOBJ OBJ((DCNC0966/A *FILE *EXCLRD A) (DCNC0966/B *FILE *EXCLRD B) (DCNC0966/M *FILE *EXCLRD M) (DCNC0966/U *FILE *EXCLRD U)) SCOPE(*JOB)');
SET HELD=0;
SET RELEASED=CURRENT_TIMESTAMP;
END;
END IF;
IF FAILED=0 AND RELEASE_FAILED=0 THEN
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION SET FAILED=1;
DECLARE EXIT HANDLER FOR SQLWARNING SET FAILED=1;
DECLARE EXIT HANDLER FOR NOT FOUND SET FAILED=1;
INSERT INTO SESSION.DCGPULSE VALUES('E0C058D978EC40ECAFAC26A5CD835BBD', '1EB812B042F605BBF5B5A5357810DE9B8F413280E3CC8E1514A8066B0B1691A3', ACQUIRED, RELEASED);
END;
END IF;
IF FAILED=1 OR RELEASE_FAILED=1 THEN
SIGNAL SQLSTATE '75001' SET MESSAGE_TEXT='Pulse failed; independent drain required';
END IF;
END
